// O(n): one pass
function sum(nums: number[]): number {
  let total = 0;
  for (const x of nums) total += x;
  return total;
}

// O(n^2): nested loops over the same input
function hasDuplicateSlow(nums: number[]): boolean {
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      if (nums[i] === nums[j]) return true;
  return false;
}

// O(n) time, O(n) extra space: trade memory for speed
function hasDuplicate(nums: number[]): boolean {
  const seen = new Set<number>();
  for (const x of nums) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}

// O(log n): the counter doubles each step
function countDoublings(n: number): number {
  let steps = 0;
  for (let i = 1; i < n; i *= 2) steps++;
  return steps;
}

// O(2^n) time, O(n) stack space
function fib(n: number): number {
  return n < 2 ? n : fib(n - 1) + fib(n - 2);
}

// O(n) time, O(n) space with memoization
function fibMemo(n: number, memo = new Map<number, number>()): number {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n)!;
  const v = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, v);
  return v;
}

