// First index i in [lo, hi) where ok(i) is true; returns hi if none.
function lowerBound(lo: number, hi: number, ok: (i: number) => boolean): number {
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (ok(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

// Exact search on a sorted array
function search(nums: number[], target: number): number {
  const i = lowerBound(0, nums.length, (k) => nums[k] >= target);
  return i < nums.length && nums[i] === target ? i : -1;
}

// First and last position of target
function searchRange(nums: number[], t: number): [number, number] {
  const first = lowerBound(0, nums.length, (k) => nums[k] >= t);
  if (first === nums.length || nums[first] !== t) return [-1, -1];
  const last = lowerBound(0, nums.length, (k) => nums[k] > t) - 1;
  return [first, last];
}

// Koko: minimum integer speed k so all piles are eaten within h hours
function minEatingSpeed(piles: number[], h: number): number {
  const hoursAt = (k: number) => piles.reduce((s, p) => s + Math.ceil(p / k), 0);
  let lo = 1, hi = Math.max(...piles);
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (hoursAt(mid) <= h) hi = mid;   // feasible: try slower
    else lo = mid + 1;
  }
  return lo;
}

function mergeSort(a: number[]): number[] {
  if (a.length <= 1) return a;
  const mid = a.length >> 1;
  const left = mergeSort(a.slice(0, mid));
  const right = mergeSort(a.slice(mid));
  const out: number[] = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length)
    out.push(left[i] <= right[j] ? left[i++] : right[j++]); // <= keeps it stable
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}

