// Power in O(log n) by halving the exponent
function pow(x: number, n: number): number {
  if (n === 0) return 1;
  if (n < 0) return 1 / pow(x, -n);
  const half = pow(x, Math.floor(n / 2));
  return n % 2 === 0 ? half * half : half * half * x;
}

function backtrackTemplate<T>(choices: T[]): T[][] {
  const res: T[][] = [];
  const path: T[] = [];
  function dfs(start: number) {
    res.push([...path]);                 // record (copy!) - here: every node is a result
    for (let i = start; i < choices.length; i++) {
      path.push(choices[i]);             // choose
      dfs(i + 1);                        // explore
      path.pop();                        // unchoose
    }
  }
  dfs(0);
  return res;                            // this instance generates all subsets
}

function permute(nums: number[]): number[][] {
  const res: number[][] = [], path: number[] = [];
  const used = new Array(nums.length).fill(false);
  function dfs() {
    if (path.length === nums.length) { res.push([...path]); return; }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true; path.push(nums[i]);
      dfs();
      used[i] = false; path.pop();
    }
  }
  dfs();
  return res;
}

function combinationSum(cands: number[], target: number): number[][] {
  const res: number[][] = [], path: number[] = [];
  cands.sort((a, b) => a - b);
  function dfs(start: number, remain: number) {
    if (remain === 0) { res.push([...path]); return; }
    for (let i = start; i < cands.length; i++) {
      if (cands[i] > remain) break;      // prune: sorted, so the rest are too big
      path.push(cands[i]);
      dfs(i, remain - cands[i]);         // i, not i + 1: reuse allowed
      path.pop();
    }
  }
  dfs(0, target);
  return res;
}

