class MinHeap<T> {
  private a: T[] = [];
  constructor(private less: (x: T, y: T) => boolean) {}
  get size() { return this.a.length; }
  peek(): T | undefined { return this.a[0]; }
  push(x: T): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.less(a[i], a[p])) break;
      [a[i], a[p]] = [a[p], a[i]];
      i = p;
    }
  }
  pop(): T | undefined {
    const a = this.a;
    if (a.length === 0) return undefined;
    const top = a[0];
    const last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.less(a[l], a[m])) m = l;
        if (r < a.length && this.less(a[r], a[m])) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]];
        i = m;
      }
    }
    return top;
  }
}
// Max-heap: new MinHeap<number>((x, y) => x > y)

function canJump(nums: number[]): boolean {
  let farthest = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > farthest) return false;          // cannot even reach i
    farthest = Math.max(farthest, i + nums[i]);
  }
  return true;
}

function merge(intervals: number[][]): number[][] {
  const sorted = [...intervals].sort((a, b) => a[0] - b[0]);
  const res: number[][] = [];
  for (const [s, e] of sorted) {
    const last = res[res.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else res.push([s, e]);
  }
  return res;
}

// Minimum meeting rooms via sweep line
function minMeetingRooms(iv: number[][]): number {
  const starts = iv.map((x) => x[0]).sort((a, b) => a - b);
  const ends = iv.map((x) => x[1]).sort((a, b) => a - b);
  let rooms = 0, best = 0, j = 0;
  for (let i = 0; i < starts.length; i++) {
    while (j < ends.length && ends[j] <= starts[i]) { j++; rooms--; }
    rooms++;
    best = Math.max(best, rooms);
  }
  return best;
}

function buildGraph(n: number, edges: [number, number][], directed = false): number[][] {
  const g: number[][] = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    g[u].push(v);
    if (!directed) g[v].push(u);
  }
  return g;
}

const DIRS = [[1, 0], [-1, 0], [0, 1], [0, -1]];

// Number of islands with iterative DFS (no recursion depth issues)
function numIslands(grid: string[][]): number {
  const R = grid.length, C = grid[0].length;
  let count = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    if (grid[r][c] !== '1') continue;
    count++;
    const stack: [number, number][] = [[r, c]];
    grid[r][c] = '0';
    while (stack.length) {
      const [x, y] = stack.pop()!;
      for (const [dx, dy] of DIRS) {
        const nx = x + dx, ny = y + dy;
        if (nx >= 0 && ny >= 0 && nx < R && ny < C && grid[nx][ny] === '1') {
          grid[nx][ny] = '0';
          stack.push([nx, ny]);
        }
      }
    }
  }
  return count;
}

// BFS shortest path (unweighted); returns distance array
function bfs(g: number[][], src: number): number[] {
  const dist = new Array(g.length).fill(-1);
  dist[src] = 0;
  let frontier = [src];
  while (frontier.length) {
    const next: number[] = [];
    for (const u of frontier)
      for (const v of g[u])
        if (dist[v] === -1) { dist[v] = dist[u] + 1; next.push(v); }
    frontier = next;
  }
  return dist;
}

function topoSort(n: number, edges: [number, number][]): number[] | null {
  const g: number[][] = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [u, v] of edges) { g[u].push(v); indeg[v]++; }
  const queue: number[] = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);
  const order: number[] = [];
  for (let h = 0; h < queue.length; h++) {   // head index instead of shift()
    const u = queue[h];
    order.push(u);
    for (const v of g[u]) if (--indeg[v] === 0) queue.push(v);
  }
  return order.length === n ? order : null;   // null => cycle
}

// Uses the MinHeap class from the heaps chapter
function dijkstra(g: [number, number][][], src: number): number[] {
  const dist = new Array(g.length).fill(Infinity);
  dist[src] = 0;
  const pq = new MinHeap<[number, number]>((a, b) => a[0] < b[0]); // [dist, node]
  pq.push([0, src]);
  while (pq.size) {
    const [d, u] = pq.pop()!;
    if (d > dist[u]) continue;                 // stale entry
    for (const [v, w] of g[u]) {
      if (d + w < dist[v]) {
        dist[v] = d + w;
        pq.push([dist[v], v]);
      }
    }
  }
  return dist;
}

class DSU {
  parent: number[];
  size: number[];
  components: number;
  constructor(n: number) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.size = new Array(n).fill(1);
    this.components = n;
  }
  find(x: number): number {
    while (this.parent[x] !== x) {
      this.parent[x] = this.parent[this.parent[x]]; // path halving
      x = this.parent[x];
    }
    return x;
  }
  union(a: number, b: number): boolean {
    let ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;                 // already connected => cycle edge
    if (this.size[ra] < this.size[rb]) [ra, rb] = [rb, ra];
    this.parent[rb] = ra;
    this.size[ra] += this.size[rb];
    this.components--;
    return true;
  }
}

// Climbing stairs / Fibonacci shape: dp[i] = dp[i-1] + dp[i-2]
function climbStairs(n: number): number {
  let a = 1, b = 1;                 // ways to reach step 0 and step 1
  for (let i = 2; i <= n; i++) [a, b] = [b, a + b];
  return b;
}

// House Robber: dp[i] = max(dp[i-1], dp[i-2] + nums[i])
function rob(nums: number[]): number {
  let prev2 = 0, prev1 = 0;
  for (const x of nums) [prev2, prev1] = [prev1, Math.max(prev1, prev2 + x)];
  return prev1;
}

// Top-down template with memo keyed by state
function minPathCost(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const memo = new Map<number, number>();
  function f(r: number, c: number): number {
    if (r === R - 1 && c === C - 1) return grid[r][c];
    if (r >= R || c >= C) return Infinity;
    const key = r * C + c;
    if (memo.has(key)) return memo.get(key)!;
    const v = grid[r][c] + Math.min(f(r + 1, c), f(r, c + 1));
    memo.set(key, v);
    return v;
  }
  return f(0, 0);
}

// Fewest coins to make amount (unbounded)
function coinChange(coins: number[], amount: number): number {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (let a = 1; a <= amount; a++)
    for (const c of coins)
      if (c <= a && dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1;
  return dp[amount] === Infinity ? -1 : dp[amount];
}

// Partition Equal Subset Sum (0/1 knapsack, boolean)
function canPartition(nums: number[]): boolean {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % 2) return false;
  const target = total / 2;
  const dp = new Array(target + 1).fill(false);
  dp[0] = true;
  for (const x of nums)
    for (let c = target; c >= x; c--)      // downward: each item used once
      dp[c] = dp[c] || dp[c - x];
  return dp[target];
}

function lengthOfLIS(nums: number[]): number {
  const tails: number[] = [];
  for (const x of nums) {
    let lo = 0, hi = tails.length;
    while (lo < hi) {                      // first tail >= x
      const mid = (lo + hi) >> 1;
      if (tails[mid] >= x) hi = mid; else lo = mid + 1;
    }
    tails[lo] = x;                         // replace or append
  }
  return tails.length;
}

function minDistance(a: string, b: string): number {
  const m = a.length, n = b.length;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = a[i - 1] === b[j - 1]
        ? prev[j - 1]
        : 1 + Math.min(prev[j], cur[j - 1], prev[j - 1]); // delete, insert, replace
    }
    prev = cur;
  }
  return prev[n];
}

